import type { ComponentType } from "react";

// Each entry is a client component importing its own bundle. Callback-bearing
// bundles cannot cross a server/client prop boundary.
export const sketches: Record<string, ComponentType> = {};
import { notFound } from "next/navigation";
import { sketches } from "@/content/sketches";

export function generateStaticParams() {
  return Object.keys(sketches).map((id) => ({ id }));
}
export default async function Sketch({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const SketchStory = Object.hasOwn(sketches, id) ? sketches[id] : undefined;
  if (!SketchStory) notFound();
  return <SketchStory />;
}
import type { Metadata } from "next";
import { copy } from "@/content/copy";
import "./globals.css";

export const metadata: Metadata = copy.metadata;
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return <html lang={copy.lang}><body>{children}</body></html>;
}
import { Chapter, Beat, Kicker, Title, Body, Note } from "@/components/story/chapter";
import { Experience } from "@/content/experience";
import { story } from "@/content/story";
import { copy } from "@/content/copy";

export default function Home() {
  return <main><a className="story-skip" href="#close">{copy.skipLabel}</a><Experience>
    {story.chapters.map((chapter, index) => <Chapter key={chapter.id} id={chapter.id}>
      {chapter.beats.map((beat, beatIndex) => {
        const words = copy.beats[beat.id];
        return <Beat key={beat.id} story={story} id={beat.id} fallback={index === 1 ?
          // A local SVG is already sized; no image optimizer or network is needed.
          // eslint-disable-next-line @next/next/no-img-element
          <img src="/plain/face.svg" width="448" height="608" alt={copy.pictureAlt} /> : undefined}>
          <Kicker number={chapter.number}>{chapter.name}</Kicker>
          <Title id={`${beatIndex === 0 ? chapter.id : beat.id}-title`} as={index === 0 && beatIndex === 0 ? "h1" : "h2"}>{words.title}</Title>
          <Body>{words.body}</Body>
          <Note>{words.note}</Note>
          {index === 2 && <a href="#opening">{copy.backLabel}</a>}
        </Beat>;
      })}
    </Chapter>)}
  </Experience></main>;
}
