    <Box p={[.42, .6, 0]} s={[.14, 1.2, .18]} color={accent} />
    <Box p={[0, 1.22, 0]} s={[.98, .16, .18]} color={accent} />
    <Box p={[0, .08, 0]} s={[1, .12, .7]} color={accent} />
