function Migration({ accent, amount }: { accent: string; amount: number }) {
  return <group position={[0, .2, 0]}>
    <Arch x={-1.4} accent="#7a847b" /><Arch x={1.4} accent={accent} />
    <Box p={[0, .13, 0]} s={[2.8, .09, .55]} color="#b6b9a8" />
